// Process ELO rating updates from match results
const { matchResults, tournamentMultiplier = 1.0, seasonMultiplier = 1.0 } = $input.first().json;

if (!matchResults || !Array.isArray(matchResults)) {
  throw new Error('Match results array is required');
}

const eloUpdates = [];

// Process each player's rating update
matchResults.forEach(playerResult => {
  const {
    playerId,
    playerName,
    previousElo,
    newElo,
    eloChange,
    opponentAverageElo,
    matchResult,
    kda,
    mvp,
    arenaType,
    wasUpset
  } = playerResult;

  // Calculate additional factors
  const performanceBonus = this.calculatePerformanceBonus(kda, mvp, wasUpset);
  const streakBonus = this.calculateStreakBonus(playerId, matchResult);

  // Apply multipliers
  const finalEloChange = Math.round(
    eloChange * tournamentMultiplier * seasonMultiplier + 
    performanceBonus + 
    streakBonus
  );

  // Calculate new league status
  const previousLeague = this.getLeague(previousElo);
  const newLeague = this.getLeague(newElo + finalEloChange);
  const leagueChanged = previousLeague !== newLeague;

  eloUpdates.push({
    playerId,
    playerName,
    previousElo,
    baseEloChange: eloChange,
    tournamentMultiplier,
    seasonMultiplier,
    performanceBonus,
    streakBonus,
    finalEloChange,
    newElo: newElo + finalEloChange,
    previousLeague,
    newLeague,
    leagueChanged,
    promotion: leagueChanged && this.isPromotion(previousLeague, newLeague),
    demotion: leagueChanged && this.isDemotion(previousLeague, newLeague),
    arenaType,
    matchResult,
    kda,
    mvp,
    wasUpset,
    timestamp: new Date().toISOString()
  });
});

return { eloUpdates };

// Calculate performance bonus based on KDA and other factors
function calculatePerformanceBonus(kda, mvp, wasUpset) {
  let bonus = 0;

  // KDA bonus
  if (kda >= 5.0) bonus += 15;
  else if (kda >= 3.0) bonus += 10;
  else if (kda >= 2.0) bonus += 5;

  // MVP bonus
  if (mvp) bonus += 8;

  // Upset bonus
  if (wasUpset) bonus += 12;

  return bonus;
}

// Calculate streak bonus (would fetch from database)
function calculateStreakBonus(playerId, matchResult) {
  // Mock implementation - would fetch current streak from database
  const mockStreak = Math.random() > 0.7 ? Math.floor(Math.random() * 5) + 1 : 0;

  if (mockStreak >= 3) return 10;
  if (mockStreak >= 5) return 20;

  return 0;
}

// Get league based on ELO
function getLeague(elo) {
  if (elo >= 2900) return 'Mythic';
  if (elo >= 2600) return 'Master';
  if (elo >= 2300) return 'Diamond';
  if (elo >= 2000) return 'Platinum';
  if (elo >= 1700) return 'Gold';
  if (elo >= 1400) return 'Silver';
  return 'Bronze';
}

// Check if it's a promotion
function isPromotion(oldLeague, newLeague) {
  const leagues = ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Master', 'Mythic'];
  return leagues.indexOf(newLeague) > leagues.indexOf(oldLeague);
}

// Check if it's a demotion
function isDemotion(oldLeague, newLeague) {
  const leagues = ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond', 'Master', 'Mythic'];
  return leagues.indexOf(newLeague) < leagues.indexOf(oldLeague);
}

return { eloUpdates };

