// Generate notifications for league changes
const eloUpdate = $input.first().json;
const notifications = [];

// League promotion notification
if (eloUpdate.promotion) {
  notifications.push({
    playerId: eloUpdate.playerId,
    type: 'league_promotion',
    title: '🎉 League Promotion!',
    message: `Congratulations! You've been promoted to ${eloUpdate.newLeague}!`,
    data: {
      previousLeague: eloUpdate.previousLeague,
      newLeague: eloUpdate.newLeague,
      newElo: eloUpdate.newElo,
      eloChange: eloUpdate.finalEloChange
    },
    rewards: this.calculatePromotionRewards(eloUpdate.newLeague),
    timestamp: eloUpdate.timestamp
  });
}

// League demotion notification
if (eloUpdate.demotion) {
  notifications.push({
    playerId: eloUpdate.playerId,
    type: 'league_demotion',
    title: 'League Demotion',
    message: `You've been demoted to ${eloUpdate.newLeague}. Keep practicing to climb back up!`,
    data: {
      previousLeague: eloUpdate.previousLeague,
      newLeague: eloUpdate.newLeague,
      newElo: eloUpdate.newElo,
      eloChange: eloUpdate.finalEloChange
    },
    timestamp: eloUpdate.timestamp
  });
}

// New personal best notification
if (eloUpdate.newElo >= eloUpdate.previousElo && eloUpdate.newElo > 2000) {
  // Check if it's a new peak (would need to compare with stored peak)
  notifications.push({
    playerId: eloUpdate.playerId,
    type: 'personal_best',
    title: '⭐ New Personal Best!',
    message: `New peak ELO rating: ${eloUpdate.newElo}!`,
    data: {
      newElo: eloUpdate.newElo,
      eloChange: eloUpdate.finalEloChange,
      league: eloUpdate.newLeague
    },
    timestamp: eloUpdate.timestamp
  });
}

return { notifications };

// Calculate promotion rewards
function calculatePromotionRewards(league) {
  const rewards = {
    'Bronze': { gold: 100, gems: 10 },
    'Silver': { gold: 250, gems: 25 },
    'Gold': { gold: 500, gems: 50 },
    'Platinum': { gold: 1000, gems: 100 },
    'Diamond': { gold: 2000, gems: 200 },
    'Master': { gold: 5000, gems: 500 },
    'Mythic': { gold: 10000, gems: 1000 }
  };

  return rewards[league] || { gold: 50, gems: 5 };
}

// Update global rankings
const eloUpdate = $input.first().json;

// Get current global ranking position
const rankingUpdate = {
  playerId: eloUpdate.playerId,
  playerName: eloUpdate.playerName,
  newElo: eloUpdate.newElo,
  previousElo: eloUpdate.previousElo,
  league: eloUpdate.newLeague,
  change: eloUpdate.finalEloChange,
  timestamp: eloUpdate.timestamp,
  region: 'global' // Would be fetched from player data
};

return { rankingUpdate };

// Generate ELO analytics data
const eloUpdates = $input.first().json;

const analytics = {
  date: new Date().toISOString().split('T')[0], // YYYY-MM-DD format
  totalUpdates: eloUpdates.length,
  averageEloChange: eloUpdates.reduce((sum, update) => sum + update.finalEloChange, 0) / eloUpdates.length,
  promotions: eloUpdates.filter(update => update.promotion).length,
  demotions: eloUpdates.filter(update => update.demotion).length,
  biggestGain: eloUpdates.reduce((max, update) => update.finalEloChange > (max?.change || 0) ? { playerId: update.playerId, playerName: update.playerName, change: update.finalEloChange, newElo: update.newElo } : max, null),
  biggestLoss: eloUpdates.reduce((min, update) => update.finalEloChange < (min?.change || 0) ? { playerId: update.playerId, playerName: update.playerName, change: update.finalEloChange, newElo: update.newElo } : min, null),
  leagueDistribution: this.calculateLeagueDistribution(eloUpdates),
  arenaTypeStats: this.calculateArenaTypeStats(eloUpdates)
};

return { analytics };

// Calculate league distribution
function calculateLeagueDistribution(updates) {
  const distribution = {};
  updates.forEach(update => {
    distribution[update.newLeague] = (distribution[update.newLeague] || 0) + 1;
  });
  return distribution;
}

// Calculate arena type statistics
function calculateArenaTypeStats(updates) {
  const stats = {};
  updates.forEach(update => {
    if (!stats[update.arenaType]) {
      stats[update.arenaType] = {
        count: 0,
        totalChange: 0,
        averageChange: 0
      };
    }
    stats[update.arenaType].count++;
    stats[update.arenaType].totalChange += update.finalEloChange;
  });

  // Calculate averages
  Object.keys(stats).forEach(arenaType => {
    stats[arenaType].averageChange = stats[arenaType].totalChange / stats[arenaType].count;
  });

  return stats;
}

